package com.huan.capture.sr.webrtc;import static org.webrtc.ContextUtils.getApplicationContext;import android.content.Context;import android.util.Log;import com.huan.capture.PeerConnectionAdapter;import com.huan.capture.SdpAdapter;import com.huan.capture.sr.webrtc.capture.VideoCaptureAdapter;import com.huan.capture.sr.webrtc.transfer.TransferAdapter;import org.webrtc.DefaultVideoDecoderFactory;import org.webrtc.DefaultVideoEncoderFactory;import org.webrtc.EglBase;import org.webrtc.IceCandidate;import org.webrtc.Logging;import org.webrtc.MediaConstraints;import org.webrtc.MediaStreamTrack;import org.webrtc.PeerConnection;import org.webrtc.PeerConnectionFactory;import org.webrtc.RtpSender;import org.webrtc.RtpTransceiver;import org.webrtc.SessionDescription;import org.webrtc.SurfaceTextureHelper;import org.webrtc.SurfaceViewRenderer;import org.webrtc.VideoCodecInfo;import org.webrtc.VideoDecoderFactory;import org.webrtc.VideoEncoderFactory;import org.webrtc.VideoSource;import org.webrtc.VideoTrack;import java.util.Collections;import java.util.List;/** * <br> * * <br> */public class WebRTCManager implements TransferAdapter.AnswerCallback {    public static final int WIDTH = 720;    public static final int HEIGHT = 1280;    public static final int FPS = 25;    private final String VIDEO_TRACK_ID = "video_0";    protected EglBase mEglBase;    protected PeerConnectionFactory mConnectionFactory;    protected PeerConnection mConnection;    private TransferAdapter mWebRTCTransferAdapter;    private VideoTrackerHolder mVideoTrackerHolder;    public void init(Context context, TransferAdapter adapter) {        mWebRTCTransferAdapter = adapter;        mWebRTCTransferAdapter.setAnswerCallback(this);        initEGLBase();        initConnectionFactory(context);        initConnection();    }    public synchronized VideoTrack createVideoTrack(VideoCaptureAdapter capture) {        SurfaceTextureHelper textureHelper = SurfaceTextureHelper.create("CaptureThread", mEglBase.getEglBaseContext());        VideoSource videoSource = mConnectionFactory.createVideoSource(capture.isScreencast());        capture.initialize(textureHelper, getApplicationContext(), videoSource.getCapturerObserver());        videoSource.setIsScreencast(capture.isScreencast());        videoSource.adaptOutputFormat(WIDTH, HEIGHT, FPS);        capture.startCapture(WIDTH, HEIGHT, FPS);        VideoTrack videoTrack = mConnectionFactory.createVideoTrack(VIDEO_TRACK_ID, videoSource);        videoTrack.setEnabled(true);        mVideoTrackerHolder = new VideoTrackerHolder();        mVideoTrackerHolder.textureHelper = textureHelper;        mVideoTrackerHolder.videoCapturer = capture;        mVideoTrackerHolder.videoSource = videoSource;        return videoTrack;    }    public boolean isVideoTrackerExist() {        return mVideoTrackerHolder != null;    }    public synchronized void replaceVideoCapture(VideoCaptureAdapter capture) {        if (mVideoTrackerHolder != null) {            capture.initialize(mVideoTrackerHolder.textureHelper, getApplicationContext(), mVideoTrackerHolder.videoSource.getCapturerObserver());            mVideoTrackerHolder.videoSource.setIsScreencast(capture.isScreencast());            capture.startCapture(WIDTH, HEIGHT, FPS);            mVideoTrackerHolder.videoCapturer = capture;        }    }    public synchronized void addVideoTrack(VideoTrack track) {        addVideoTrack(track, null);    }    public synchronized void addVideoTrack(VideoTrack track, SurfaceViewRenderer renderer) {        if (renderer != null) {            renderer.setMirror(false);            renderer.init(mEglBase.getEglBaseContext(), null);            track.addSink(renderer);            mVideoTrackerHolder.renderer = renderer;        }        RtpSender sender = null;        for (RtpSender _sender : mConnection.getSenders()) {            List<String> streams = _sender.getStreams();            if (streams != null && streams.contains(VIDEO_TRACK_ID)) {                sender = _sender;                break;            }        }        if (sender != null) {            sender.setTrack(track, true);            return;        }        mConnection.addTrack(track);    }    private void initEGLBase() {        mEglBase = EglBase.create();        mEglBase.createDummyPbufferSurface();        mEglBase.makeCurrent();    }    private void initConnectionFactory(Context context) {        PeerConnectionFactory.initialize(                PeerConnectionFactory.InitializationOptions                        .builder(context.getApplicationContext())                        .setEnableInternalTracer(true)                        .createInitializationOptions()        );        PeerConnectionFactory.Options options = new PeerConnectionFactory.Options();        options.networkIgnoreMask = 0;        options.disableEncryption = true;        options.disableNetworkMonitor = true;        EglBase.Context eglBaseContext = mEglBase.getEglBaseContext();        VideoEncoderFactory videoEncoderFactory =                new DefaultVideoEncoderFactory(eglBaseContext, true, true);        VideoDecoderFactory videoDecoderFactory = new DefaultVideoDecoderFactory(eglBaseContext);        videoEncoderFactory = new H264OnlyEncoderFactory(eglBaseContext);        videoDecoderFactory = new H264OnlyDecoderFactory(eglBaseContext);        mConnectionFactory = PeerConnectionFactory.builder()                .setVideoEncoderFactory(videoEncoderFactory)                .setVideoDecoderFactory(videoDecoderFactory)                .setOptions(options)                .createPeerConnectionFactory();        Logging.enableLogToDebugOutput(Logging.Severity.LS_INFO);        VideoCodecInfo[] encodeCodecs = videoEncoderFactory.getSupportedCodecs();        for (VideoCodecInfo codec : encodeCodecs) {            Log.d("sunrain", "encodeCodecs " + codec.toString());        }        VideoCodecInfo[] decodeCodecs = videoDecoderFactory.getSupportedCodecs();        for (VideoCodecInfo codec : decodeCodecs) {            Log.d("sunrain", "decodeCodecs " + codec.toString());        }    }    private void initConnection() {        mConnection = mConnectionFactory.createPeerConnection(                Collections.emptyList(),                new PeerConnectionAdapter("screenCapAdapter") {                    @Override                    public void onIceCandidate(IceCandidate iceCandidate) {                        super.onIceCandidate(iceCandidate);                        if (mWebRTCTransferAdapter != null) {                            mWebRTCTransferAdapter.onIceCandidate(iceCandidate);                        }                    }                }        );        MediaConstraints constraints = new MediaConstraints();        constraints.mandatory.add(new MediaConstraints.KeyValuePair("maxFrameRate", "20"));        constraints.mandatory.add(new MediaConstraints.KeyValuePair("OfferToReceiveVideo", "false"));        constraints.mandatory.add(new MediaConstraints.KeyValuePair("OfferToReceiveAudio", "false"));        mConnection.addTransceiver(MediaStreamTrack.MediaType.MEDIA_TYPE_VIDEO,                new RtpTransceiver.RtpTransceiverInit(                        RtpTransceiver.RtpTransceiverDirection.SEND_ONLY,                        Collections.singletonList(VIDEO_TRACK_ID)                ));        mConnection.createOffer(new SdpAdapter("OFFER") {            @Override            public void onCreateSuccess(SessionDescription sdp) {                super.onCreateSuccess(sdp);                mConnection.setLocalDescription(new SdpAdapter("LOCAL_DSP"), sdp);                mWebRTCTransferAdapter.sendOfferSdp(sdp);            }        }, constraints);    }    @Override    public void onAnswerSdp(SessionDescription sdp) {        mConnection.setRemoteDescription(new SdpAdapter("REMOTE_DSP"), sdp);    }    public void stopCurrentVideoCapture(boolean clearRenderer) {        if (mVideoTrackerHolder != null) {            try {                mVideoTrackerHolder.videoCapturer.stopCapture();            } catch (InterruptedException ignore) {            }            mVideoTrackerHolder.videoCapturer.dispose();            if (clearRenderer) {                mVideoTrackerHolder.renderer.clearImage();            }        }    }    public void release() {        if (mVideoTrackerHolder != null) {            mVideoTrackerHolder.videoCapturer.dispose();            mVideoTrackerHolder.videoSource.dispose();            mVideoTrackerHolder.renderer.clearImage();            mVideoTrackerHolder.renderer.release();            mVideoTrackerHolder.textureHelper.dispose();            mVideoTrackerHolder = null;        }    }    public void destroy() {        if (mConnection != null) {            mConnection.dispose();            mConnection = null;        }        if (mConnectionFactory != null) {            mConnectionFactory.dispose();            mConnectionFactory = null;        }        if (mEglBase != null) {            mEglBase.release();            mEglBase = null;        }    }    private static final class VideoTrackerHolder {        public SurfaceTextureHelper textureHelper;        private VideoCaptureAdapter videoCapturer;        private VideoSource videoSource;        public SurfaceViewRenderer renderer;    }}